<link rel="stylesheet" href="<?= URL_ROOT ?>/public/css/system-log.css?v=<?= filemtime(APP_ROOT.'/public/css/system-log.css') ?>">
<div class="container-fluid log-shell pb-4"><?php if(Session::get('system_log_msg')): ?><div class="alert alert-success"><?= htmlspecialchars(Session::get('system_log_msg'));Session::delete('system_log_msg'); ?></div><?php endif; ?><div class="d-flex justify-content-between align-items-center mb-3"><div><a href="<?= URL_ROOT ?>/admin/system-log/<?= $type ?>" class="small text-decoration-none"><i class="fa-solid fa-arrow-left me-1"></i>Quay lại</a><h2 class="h4 fw-bold mt-2">Chi tiết <?= ucfirst($type) ?> Log #<?= (int)$row->id ?></h2></div><?php if($type==='error'): ?><form method="POST" action="<?= URL_ROOT ?>/admin/system-log/resolve/<?= $row->id ?>"><?= Csrf::field() ?><input type="hidden" name="resolved" value="<?= $row->resolved?0:1 ?>"><button class="btn btn-sm <?= $row->resolved?'btn-outline-warning':'btn-success' ?>"><?= $row->resolved?'Mở lại lỗi':'Đánh dấu đã xử lý' ?></button></form><?php endif; ?></div>
<div class="card log-card mb-3"><div class="card-body"><div class="row g-3"><?php foreach((array)$row as $key=>$value): if(in_array($key,['stack_trace','old_data','new_data','metadata','context'],true))continue; ?><div class="col-lg-4 col-md-6"><div class="small text-muted text-uppercase fw-bold"><?= htmlspecialchars(str_replace('_',' ',$key)) ?></div><div class="mt-1 text-break"><?= htmlspecialchars($value===null?'—':(string)$value) ?></div></div><?php endforeach; ?></div></div></div>
<?php foreach(['metadata'=>'Metadata','old_data'=>'Dữ liệu cũ','new_data'=>'Dữ liệu mới','context'=>'Context'] as $key=>$label): if(!empty($row->$key)): $decoded=json_decode($row->$key,true); ?><div class="card log-card mb-3"><div class="card-body"><h6 class="fw-bold"><?= $label ?></h6><pre class="log-json mb-0"><?= htmlspecialchars(json_encode($decoded??$row->$key,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></pre></div></div><?php endif;endforeach; ?>
<?php if(!empty($row->stack_trace)): ?><div class="card log-card"><div class="card-body"><h6 class="fw-bold">Stack Trace</h6><pre class="log-code mb-0"><?= htmlspecialchars($row->stack_trace) ?></pre></div></div><?php endif; ?></div>
